126	/**
127	 * Resolves the requested model alias (e.g., 'auto', 'pro', 'flash', 'flash-lite')
128	 * to a concrete model name.
129	 *
130	 * @param requestedModel The model alias or concrete model name requested by the user.
131	 * @param useGemini3_1 Whether to use Gemini 3.1 Pro Preview for auto/pro aliases.
132	 * @param useGemini3_5Flash Whether to use Gemini 3.5 Flash GA.
133	 * @param hasAccessToPreview Whether the user has access to preview models.
134	 * @returns The resolved concrete model name.
135	 */
136	export function resolveModel(
137	  requestedModel: string,
138	  useGemini3_1: boolean = false,
139	  useCustomToolModel: boolean = false,
140	  hasAccessToPreview: boolean = true,
141	  config?: ModelCapabilityContext,
142	  useGemini3_5Flash: boolean = false,
143	): string {
144	  // Defensive check against non-string inputs at runtime
145	  const normalizedModel = Array.isArray(requestedModel)
146	    ? String(requestedModel.at(-1) ?? '').trim() || ''
147	    : typeof requestedModel !== 'string'
148	      ? String(requestedModel ?? '').trim() || ''
149	      : requestedModel.trim() || '';
150	
151	  if (config?.getExperimentalDynamicModelConfiguration?.() === true) {
152	    const resolved = config.modelConfigService.resolveModelId(normalizedModel, {
153	      useGemini3_1,
154	      useCustomTools: useCustomToolModel,
155	      hasAccessToPreview,
156	      useGemini3_5Flash,
157	    });
158	
159	    if (!hasAccessToPreview && isPreviewModel(resolved, config)) {
160	      // Fallback for unknown preview models.
161	      if (resolved.includes('flash-lite')) {
162	        return DEFAULT_GEMINI_FLASH_LITE_MODEL;
163	      }
164	      if (resolved.includes('flash')) {
165	        return useGemini3_5Flash
166	          ? DEFAULT_GEMINI_3_5_FLASH_MODEL
167	          : DEFAULT_GEMINI_FLASH_MODEL;
168	      }
169	      return DEFAULT_GEMINI_MODEL;
170	    }
171	
172	    return resolved;
173	  }
174	
175	  let resolved: string;
176	  switch (normalizedModel) {
177	    case GEMINI_MODEL_ALIAS_AUTO:
178	    case GEMINI_MODEL_ALIAS_PRO: {
179	      if (!hasAccessToPreview) {
180	        resolved = DEFAULT_GEMINI_MODEL;
181	        break;
182	      }
183	      // fallthrough
184	    }
185	    case PREVIEW_GEMINI_MODEL:
186	    case PREVIEW_GEMINI_MODEL_AUTO: {
187	      if (useGemini3_1) {
188	        resolved = useCustomToolModel
189	          ? PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL
190	          : PREVIEW_GEMINI_3_1_MODEL;
191	      } else {
192	        resolved = PREVIEW_GEMINI_MODEL;
193	      }
194	      break;
195	    }
196	    case DEFAULT_GEMINI_MODEL_AUTO: {
197	      resolved = DEFAULT_GEMINI_MODEL;
198	      break;
199	    }
200	    case GEMINI_MODEL_ALIAS_FLASH: {
201	      resolved = useGemini3_5Flash
202	        ? DEFAULT_GEMINI_3_5_FLASH_MODEL
203	        : PREVIEW_GEMINI_FLASH_MODEL;
204	      break;
205	    }
206	    case GEMINI_MODEL_ALIAS_FLASH_LITE: {
207	      resolved = DEFAULT_GEMINI_FLASH_LITE_MODEL;
208	      break;
209	    }
210	    default: {
211	      resolved = normalizedModel;
212	      break;
213	    }
214	  }
215	
216	  if (resolved === 'none') {
217	    return DEFAULT_GEMINI_FLASH_LITE_MODEL;
218	  }
