147	  /**
148	   * Returns a standardized list of available model options based on the resolution context.
149	   * This logic is shared across the TUI and ACP mode.
150	   */
151	  getAvailableModelOptions(context: ResolutionContext): Array<{
152	    modelId: string;
153	    name: string;
154	    description: string;
155	    tier: string;
156	  }> {
157	    const definitions = this.config.modelDefinitions ?? {};
158	    const shouldShowPreviewModels = context.hasAccessToPreview ?? false;
159	    const useGemini31 = context.useGemini3_1 ?? false;
160	
161	    const mainOptions = Object.entries(definitions)
162	      .filter(([_, m]) => {
163	        if (m.isVisible !== true) return false;
164	        if (m.isPreview && !shouldShowPreviewModels) return false;
165	        if (m.tier !== 'auto') return false;
166	        return true;
167	      })
168	      .map(([id, m]) => {
169	        let description = m.dialogDescription ?? '';
170	        if (id === 'auto') {
171	          description = getAutoModelDescription(
172	            shouldShowPreviewModels,
173	            useGemini31,
174	          );
175	        } else if (id === 'auto-gemini-3' && useGemini31) {
176	          description = description.replace('gemini-3-pro', 'gemini-3.1-pro');
177	        }
178	
179	        return {
180	          modelId: id,
181	          name: m.displayName ?? getDisplayString(id),
182	          description,
183	          tier: m.tier ?? 'auto',
184	        };
185	      });
186	
187	    const manualOptions = Object.entries(definitions)
188	      .filter(([id, m]) => {
189	        if (m.isVisible !== true) return false;
190	        if (m.isPreview && !shouldShowPreviewModels) return false;
191	        if (m.tier === 'auto') return false;
192	        if (context.hasAccessToProModel === false && isProModel(id))
193	          return false;
194	        if (id === PREVIEW_GEMINI_3_1_MODEL && !useGemini31) return false;
195	        return true;
196	      })
197	      .map(([id, m]) => {
198	        const resolvedId = this.resolveModelId(id, context);
199	        const titleId = this.resolveModelId(id, {
200	          useGemini3_1: useGemini31,
201	        });
202	        return {
203	          modelId: resolvedId,
204	          name: m.displayName ?? getDisplayString(titleId),
205	          description: m.dialogDescription ?? '',
206	          tier: m.tier ?? 'custom',
207	        };
208	      });
209	
210	    // Deduplicate manual options
211	    const seen = new Set<string>();
212	    const uniqueManualOptions = manualOptions.filter((option) => {
213	      if (seen.has(option.modelId)) return false;
214	      seen.add(option.modelId);
215	      return true;
216	    });
217	
218	    return [...mainOptions, ...uniqueManualOptions];
219	  }
