221	  getModelDefinition(modelId: string): ModelDefinition | undefined {
222	    const definition = this.config.modelDefinitions?.[modelId];
223	    if (definition) {
224	      return definition;
225	    }
226	
227	    // For unknown models, return an implicit custom definition to match legacy behavior.
228	    if (!modelId.startsWith('gemini-')) {
229	      return {
230	        tier: 'custom',
231	        family: 'custom',
232	        features: {},
233	      };
234	    }
235	
236	    return undefined;
237	  }
