243	  private matches(
244	    condition: ResolutionCondition,
245	    context: ResolutionContext,
246	  ): boolean {
247	    return Object.entries(condition).every(([key, value]) => {
248	      if (value === undefined) return true;
249	
250	      switch (key) {
251	        case 'useGemini3_1':
252	          return value === context.useGemini3_1;
253	        case 'useGemini3_1FlashLite':
254	          return value === context.useGemini3_1FlashLite;
255	        case 'useGemini3_5Flash':
256	          return value === context.useGemini3_5Flash;
257	        case 'useCustomTools':
258	          return value === context.useCustomTools;
259	        case 'hasAccessToPreview':
260	          return value === context.hasAccessToPreview;
261	        case 'requestedModels':
262	          return (
263	            Array.isArray(value) &&
264	            !!context.requestedModel &&
265	            value.includes(context.requestedModel)
266	          );
267	        default:
268	          return false;
269	      }
270	    });
271	  }
